export default function ({ events, previous }) {
  let i = previous?.index ?? 0;
  while (
    i < events.length &&
    events[i].mimeType !== "application/pdf" &&
    !/^image\//.test(events[i].mimeType)
  )
    i++;
  if (
    i < events.length &&
    events[i].mimeType.startsWith("image/") &&
    !/^image\/(png|jpeg|webp|heic|heif)$/.test(events[i].mimeType)
  )
    throw Error("Unsupported image MIME type: " + events[i].mimeType);
  let more = i < events.length;
  if (more && !events[i].fileId) throw Error("Missing source file ID");
  return {
    state: { index: i + 1 },
    more,
    file: more ? events[i] : { fileId: "placeholder", name: "", mimeType: "" },
  };
}

