export default function ({ body }) {
  if (typeof body?.text !== "string" || !body.text.trim()) throw Error("No PDF text extracted");
  return {
    input: [
      {
        role: "user",
        content: [
          {
            type: "input_text",
            text:
              "Extract every transaction into CSV and add a category column. Return only CSV, preserve numbers and do not invent missing data. Statement: " +
              body.text,
          },
        ],
      },
    ],
  };
}

