export default function ({ body, file }) {
  if (
    typeof body?.uri !== "string" ||
    !body.uri.startsWith("https://generativelanguage.googleapis.com/") ||
    body.mimeType !== file.mimeType
  )
    throw Error("Invalid Gemini file reference");
  return {
    body: {
      contents: [
        {
          parts: [
            {
              text: "Extract all transactions into CSV and add a category column. Preserve numbers, do not invent missing data, return only CSV.",
            },
            { file_data: { mime_type: body.mimeType, file_uri: body.uri } },
          ],
        },
      ],
    },
  };
}

