function validate({ text }) {
  if (typeof text !== "string") throw Error("Missing CSV response");
  const csv = text
    .trim()
    .replace(/^```(?:csv)?\s*\n/i, "")
    .replace(/\n```\s*$/, "");
  let rows = [],
    row = [],
    cell = "",
    quoted = false;
  for (let i = 0; i < csv.length; i++) {
    let c = csv[i];
    if (quoted) {
      if (c === '"' && csv[i + 1] === '"') {
        cell += '"';
        i++;
      } else if (c === '"') quoted = false;
      else cell += c;
    } else if (c === '"') {
      if (cell) throw Error("Invalid CSV quoting");
      quoted = true;
    } else if (c === ",") {
      row.push(cell);
      cell = "";
    } else if (c === "\n") {
      row.push(cell);
      rows.push(row);
      row = [];
      cell = "";
    } else if (c !== "\r") cell += c;
  }
  if (quoted) throw Error("Unclosed CSV quote");
  if (cell || row.length) {
    row.push(cell);
    rows.push(row);
  }
  if (
    !rows.length ||
    !rows[0].some((x) => x.trim().toLowerCase() === "category") ||
    rows.some((r) => r.length !== rows[0].length)
  )
    throw Error("Invalid transaction CSV");
  return { csv };
}

export default function ({ body, statusCode }) {
  if (statusCode < 200 || statusCode >= 300 || body?.candidates?.[0]?.finishReason !== "STOP")
    throw Error("Gemini image response incomplete");
  return validate({ text: body.candidates[0].content.parts.map((p) => p.text ?? "").join("") });
}

