export default function ({ response }) {
  if (response?.status && response.status !== "completed") throw Error("Model response incomplete");
  return validate({
    text:
      response?.output_text ??
      response?.output
        ?.flatMap((x) =>
          x.type === "message"
            ? (x.content ?? []).filter((p) => p.type === "output_text").map((p) => p.text)
            : [],
        )
        .join("\n"),
  });
}

