export default async function ({ id, csv, name }, ctx) {
  name = (name.replace(/\.[^.]+$/, "") || "statement") + "-" + id + ".csv";
  const key = "statement-csv:" + id,
    s = await ctx.state.get(key);
  if (s?.status === "pending")
    throw Error("Inspect destination folder before retrying uncertain upload");
  if (s?.status === "done") return { skip: true, key, csv, name };
  await ctx.state.set(key, { status: "pending" });
  return { skip: false, key, csv, name };
}

